import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:bodytmi/bodytmi.dart';
import 'package:bodytmi_core/bodytmi_core.dart';
import 'package:sqlite3/sqlite3.dart';

Future<void> main(List<String> arguments) async {
  try {
    if (arguments.isEmpty ||
        (arguments.length == 1 && arguments.single == '--help')) {
      stdout.writeln(
        jsonEncode({
          'schemaVersion': 1,
          'commands': [
            ...commandNames,
            ...storedCommandNames,
            ...foodCommandNames,
            ...sleepCommandNames,
            ...dailyCommandNames,
            ...planningCommandNames,
          ],
          'usage': 'bodytmi <group> <action> [--input FILE|-]',
          'input': 'One JSON request, schemaVersion: 1, from stdin or --input.',
          'storage':
              'store commands require a database path in the JSON request. Existing commands use explicit snapshots.',
          'backup':
              'create requires database/destination; validate requires source; restore requires database/source/recoveryDestination/confirm:true. Backup paths are directories.',
          'archive':
              'export requires database/destination; validate requires source; restore requires database/source/recoveryDestination/confirm:true. Logical exports are JSON files; recovery backups are directories.',
          'skipRemaining':
              'store skip-remaining takes database/id/expectedVersion/confirm:true and skips all planned efforts without changing completed results or finishing the session. Stop and review or discard session clocks first; use execution skip-group during traversal. session skip-remaining takes session/confirm:true and requires the caller to account for external clock/traversal state.',
          'skipSlot':
              'store skip-slot takes database/id/expectedVersion/slotId/confirm:true and optional role (work, warmup, backoff or drop); session skip-slot takes session/slotId/confirm:true and optional role. The same clock and traversal safeguards apply.',
          'editTarget':
              'store save-back takes database/id/mode and confirm:true when publishing (policy bodytmi-save-back/1, the Q35 choices): mode session keeps every edit session-only and only reports the diff; save publishes one revision when the session\'s explicit target edits change the prescription; increment always publishes a visible revision boundary. Edited targets become per-effort targets on their authored effort (every occurrence of a repeated effort must agree); actual results are never copied, and progression-controlled metrics, program overrides, substituted sets and metrics without an authored slot target stay session-only (listed in notSaved with a reason). If the template head moved past the session revision, save-back conflicts unless newTemplateId saves a separate template. The session keeps its pinned revision. session edit-target takes session/setId/metric/value and optional applyToRemaining; store edit-target takes database/id/expectedVersion/setId/metric/value and optional applyToRemaining. Edits planned suggestions only; explicit carry skips authored, derived and manually edited targets. Stored edits cannot change sets with active or unreviewed effort clocks.',
          'carryActual':
              'session carry-actual takes session/setId/metric; store carry-actual takes database/id/expectedVersion/setId/metric. Copies one completed actual to later compatible untouched suggestions in the same slot and role, with the same safeguards as edit-target.',
          'progression':
              'propose requires database/sessionId/slotId/rule; accept requires database/sessionId/slotId/expectedVersion/acceptedAt; decline requires database/sessionId/slotId/expectedVersion/declinedAt; show requires database/sessionId/slotId. Declines hold targets and resolve exposure counters once. reopen requires database/sessionId/slotId/expectedVersion/confirm:true (optional role): after correcting the results of a session whose exposure was already accepted or declined, it returns that decision to pending, re-evaluated from the corrected results against the same prior track state, for a fresh accept or decline. Only the newest anchor of an unlinked track can reopen, and only while no later session of the same template and run exists; otherwise reconcile. Stored application supports manual double, numeric threshold and ordinal level progression; propose accepts optional ruleType:threshold (all/roundRobin/weighted/chosen/priority coordination) or ruleType:ordinal with the corresponding rule. Chosen requires coordination.metric; priority requires a unique order and selects one candidate applicable across the complete target vector, with blocked-set explanations. Chosen/priority retain a zero cursor. Threshold performance:{direction:higher/lower,failureLimit,advancementLimit} replaces legacy minimum/threshold when supplied and is independent of lever directions. Best follows performance direction. Threshold rule aggregation supports all/any/best/last/total/kOfN (count required); failureAggregation supports all (default) or total. Threshold directions map controlled metrics to increase (default) or decrease; increments remain positive step sizes, minimums/maximums are inclusive lever bounds, and configured deloads move in the easier direction. Missing work stays unknown and failure gates advancement. Only accepted applicable transitions consume coordinator positions. reconcile-status takes database/templateId/revision/slotId/asOf and optional role, runId, sessionId, rule and ruleType; it reports the accepted track, the candidate prescription/session views and every named difference (workingSetCount, slotTarget, metricDimension, effortTarget, objectiveCriteria, sessionTarget, rule) that makes a later store start or progression propose need explicit reconciliation. Conflicts now name these kinds too. Reporting writes nothing and reconciles nothing. reconcile takes database/id/templateId/revision/slotId/expectedSequence/kinds/reconciledAt/confirm:true and optional role, runId, sessionId, rule, ruleType, resetFailures and resetCursor; it records one durable receipt that supersedes the resolved track anchor, adopts only the planned suggestions of the candidate prescription or session, carries failure counters and coordinator positions unless explicitly reset, and requires kinds to equal the current blocker kinds; expectedSequence is compare-and-set and one identity records one act. reconcile-show takes database/id; reconcile-list takes database. A receipt re-anchors later store starts, plan refreshes and proposals without replaying prior terminal decisions, counters or program advancement. Threshold rules may declare retest:{metric,repetitions:{metric,minimum},factor,roundTo?,stage?,restartStage?}: where the rule would deload (staged tiers: on exhausting the last stage) the outcome is retest (targets held, failures reset; nextStage plans the optional test stage, whose authored variant branch replaces the lift in the next session). progression retest takes database/id/templateId/revision/slotId/sourceSessionId/sourceSetId/expectedSequence/reseededAt/confirm:true and optional role/runId: the named set (any finalized session, same exercise/implementation/equipment, completed, uninterrupted, at least the minimum repetitions) reseeds the metric at factor × its actual (floored to roundTo) at the restart stage with failures and cursor reset, as a receipt with retest provenance. Nothing counts unless named; progression track reports retestPending. Propose rejects a session that planned the test stage. Substituted sets (store substitute) are not an exposure of the original slot unless propose takes countSubstitutes:true: they then count, reading as the original prescription with the controlled lever done as planned (e.g. dumbbell bench counting toward the barbell bench reps), while their performance metrics stay as recorded; the decision stores countSubstitutes and responses list countedSubstitutes. Their series and records keep the substitute context.',
          'observations':
              'session annotate takes session/setId/observations; store annotate takes database/id/expectedVersion/setId/observations. Replaces optional rpe:{value:decimal string,scale:0-10 or 6-20}, rir:nonnegative decimal string, notes (up to 4000 characters), terminationReason:target-reached/max-effort/grip-failure/pain-discomfort/interrupted/other. RPE/RIR require completed actuals. Empty observations clears with confirm:true. Interrupted sets remain in raw reports but are excluded from prefill, stored progression and records. Other reasons are descriptive. Stop the associated active effort clock before annotating.',
          'effortConditions':
              'Threshold rules optionally declare advancementEffort:{rpe:{scale:0-10/6-20,minimum?,maximum?},rir:{minimum?,maximum?}} with decimal-string inclusive bounds. All configured ratings on all required results must qualify. Only advancement is gated: numeric failures/deloads retain precedence; a known unmet gate holds and resets failures, while missing/mismatched ratings at the advancement boundary yield unknown and preserve failures. RPE scales never convert; pain notes remain descriptive. Pure progression evaluate accepts an aligned observations array; stored threshold proposals use the frozen set observations. Interrupted observations make results unknown. Rule changes require reconciliation.',
          'ordinalProgression':
              'ruleType:ordinal rules move the controlled target vector between explicitly authored levels. Rule shape: metric (performance metric), performance:{direction:higher/lower,failureLimit,advancementLimit} (required, inclusive), levels:[{id,targets}] ordered easiest to hardest (1-1000 levels, identical controlled metric keys and dimensions, distinct vectors), optional aggregation/failureAggregation (same modes as threshold rules), optional advancementEffort (same effort gate), optional deloadAfter and deloadLevel (an explicit easier level id). Levels carry complete working targets; harder direction is authored order, never inferred from numbers. Evaluation locates the current level by exact canonical match of every set suggestion; anything else yields review with no counter change. Outcomes: unknown, failed, deload, hold, advance, blocked at the hardest level or at an unreachable deloadLevel. Advance/deload move every working set to one level atomically; there is no coordinator position. Pure command progression ordinal takes rule/currentSets/results/state/optional observations. Later store starts consume accepted level targets. Ordinal levers cannot back shared lever links.',
          'derivedTargets':
              'target resolve evaluates an explicit acyclic graph of source, scale, add, subtract and round nodes. Sources declare unit, sourceId, sourceVersion and value (null when missing); scales declare unit, input and decimal-string factor; add/subtract declare unit, left and right dependencies; round declares input, native scale and rounding policy. Results retain source provenance, use exact canonical arithmetic, propagate missing inputs, and reject negative subtraction.',
          'derivedTargetSnapshots':
              'target capture takes an authored graph and explicit bindings keyed by sourceId, each with version and value. Missing bindings remain unresolved. target status takes a captured snapshot and current bindings, verifies the snapshot and reports source changes and both resolutions. These pure commands do not publish, persist or refresh workout sessions.',
          'derivedTargetGraphs':
              'graph validate takes a reusable graph with source/scale nodes and per-source binding policies: manual (version + value), bodyMass (context, optional asOf and resolver options) or history (metric, direction highest/lowest, optional template/slot/exercise/implementation/equipment/setup/role/ordinal scope, inclusive from, exclusive until, includeWarmups). graph publish requires database/graph/expectedRevision; show takes database/graphId and optional revision; list returns all revisions. graph resolve takes database/graphId, optional revision and asOf, and optional runId or allRuns:true. History defaults to ad hoc sessions; runId selects one run, allRuns explicitly combines all contexts. asOf excludes history finalized after the cutoff and constrains body mass. Body-mass and history provenance include compact source fingerprints (policies body-mass-ewma/2 and bodytmi-history-source/2: a count and a SHA-256 over every eligible source, plus the selected history result in full), so insertions, removals and corrections are detected without storing the whole history; their sourceVersion values describe only the maximum individual measurement version or selected session version, not a series version. Resolution returns per-source provenance plus the exact resolution. Resolving never modifies graphs, sessions or progression; unresolved sources propagate without inventing values.',
          'graphPreview':
              'graph preview takes database/templateId/revision/graphId/graphRevision/asOf/bindings and optional runId. Each binding maps occurrenceId/metric/nodeId. It previews explicit graph-derived targets without publishing, starting or changing a session. Unresolved values remain unknown; ordinary history prefill and accepted progression are not applied.',
          'graphWorkoutPlans':
              'Published graphs may include plans with id/templateId/revision/bindings; each binding selects occurrenceId/metric/nodeId. Publishing validates the pinned workout and units. graph plan-preview takes database/graphId/graphRevision/planId/asOf and optional runId to preview a saved plan. Plans can also be selected at session start.',
          'derivedSessionPlans':
              'store start and run start optionally accept derivedPlan:{graphId,graphRevision,planId}. Published plans with manual, body-mass or history graph sources and numeric targets or bounded objectives are frozen and applied at start. History is scoped to the selected run or ad hoc context, and requires earlier finalized sessions. Overlap with accepted progression is rejected; observe and max-effort objectives cannot receive suggestions. Retry must use the same plan reference.',
          'derivedSessionPlanStatus':
              'store plan-status takes database/id and compares the stored session’s frozen plan and source evidence with current inputs at its original start cutoff and run scope. Sessions without a derived plan report configured:false. History must have started before the session and finished by its start time. It is read-only and does not change session suggestions or progression. store plan-refresh takes database/id/expectedVersion/expectedPreview/confirm:true, where expectedPreview is comparison.currentPreview from store plan-status. It verifies that preview atomically and re-resolves the same pinned plan before work, timing or traversal; it does not change slot body-mass inputs.',
          'graphPlanStatus':
              'graph plan-status takes database/planPreview from graph plan-preview. It verifies that the mapping is the published plan and reports source and target changes in its original scope. Captured source evidence is caller-provided and not authenticated; no session is started or modified.',
          'graphPreviewStatus':
              'graph preview-status takes database/preview from graph preview and compares its pinned workout, graph, source fingerprints and mapped values with current data in the same scope. Caller-supplied preview evidence is not authenticated; this read-only query does not authorize or start a session.',
          'graphStatus':
              'graph status takes database/snapshot from graph resolve, checks graph revision, scope and arithmetic, then compares the captured sources with a fresh resolution in the same scope. The supplied snapshot is caller-provided evidence, not an authenticated audit record; status never changes a session or progression.',
          'publishedObjectives':
              'Effort objectives may declare exact, minimum, maximum, range, observe or maxEffort criteria using the objective evaluate schema. Maximum/range require an explicit upperMeaning. Bounds are descriptive, not prohibited actuals or automatic progression rules. Numeric suggestions remain independently accepted; observe/maxEffort require explicitly entered actuals. Targetless objectives require an explicit actual. Pinned criteria appear in session summaries/series, and changed working objectives require progression reconciliation.',
          'objectiveAssessment':
              'objective evaluate takes objectives and actuals; session assess-objectives takes session/setId/objectives; store assess-objectives takes database/id/setId/objectives. Criteria are explicitly supplied for this read-only query, not saved to the workout. Modes: exact(value), minimum(minimum), maximum(maximum,upperMeaning), range(minimum,maximum,upperMeaning), observe(unit), maxEffort(unit:rep). upperMeaning is desiredCeiling/progressionThreshold/stoppingCue. Bounds are inclusive, missing values stay unknown, and the report never applies progression or delivers cues.',
          'objectives':
              'Effort activities may declare objectives:{metric:{mode:maxEffort,unit:rep}}. Each declared repetition metric is explicitly observed without a numeric suggestion; acceptSuggested cannot supply it. Completion, execution and timer confirmation require its actual count, including an explicit zero. Threshold progression can use these actuals without inventing targets. Changing working objective modes requires progression reconciliation. Time-window AMRAP remains pending.',
          'effortTargets':
              'Effort activities may declare nonempty targets overrides for existing slot metrics with compatible dimensions. Other metrics inherit slot targets; repeat occurrences retain independent results. Authored overrides take precedence over history prefill for those metrics. Published slot timing defaults must resolve for each authored override. Accepted progression can supply controlled working targets when the authored baseline is unchanged; changed controlled per-effort targets require reconciliation. Warmups stay independent.',
          'incrementBands':
              'Threshold rules optionally declare incrementBands:{aggregation:{mode:last/best/total},bands:[{id,threshold, increments}]}. Thresholds use the performance metric/direction and must be strictly ordered from easier to harder; strongest qualifying inclusive band replaces every base increment with compatible positive steps. Otherwise base steps apply. Numeric/effort gates precede selection; bounds hold the whole vector without falling back to a lesser band. Existing coordinator selection, native scale rounding and resets remain explicit. Proposals expose incrementBandAssessment. This is generic performance-dependent stepping, including last-set bonus steps.',
          'scales':
              'scale validate takes scale{id,unit} with exactly one of ticks:[{id,value,labels?}] or range:{start,step,count,idPrefix?}. Fixed ranges declare 1–1000 native positions with a positive step and deterministic tick IDs. scale resolve also takes target/rounding (nearest/atMost/atLeast), with optional beyond/direction together. Threshold scales bind controlled metrics to frozen scale/rounding/deloadRounding; directional lookup excludes the current setting and records selected ticks. These are nominal numeric settings; inventories and plate arrangements remain separate. A threshold scale binding may instead be {instance:true, rounding, deloadRounding?}: stored progression rounds to the positions of the slot\'s bound session instance (else the one performedOn instance of every working set), i.e. every total its declared plates can make, or its selector markings; pure evaluation of such a rule is a validation error.',
          'bodyMass':
              'mass record/update/delete/show/list/trend/resolve use stored observations and require database. Measurements may include optional source and notes; updates replace the observation and require expectedVersion. Deletion requires expectedVersion and confirm:true. measurement trend/resolve still take explicit measurement arrays.',
          'sessionBodyMass':
              'Slots may explicitly configure bodyMass.context and resolver options. Session starts freeze selected inputs; optional bodyMassOverrides maps slot IDs to measurementId or mass overrides. store mass-status takes database/id; session mass-status takes session/measurements. Source changes do not rewrite captured inputs. store mass-refresh requires database/id/expectedVersion/confirm:true and explicitly recaptures slot mass at the original start cutoff before work, timing or traversal; session mass-refresh accepts session/measurements/confirm:true. Existing overrides and derived plans stay pinned. store mass-rebind takes database/id/expectedVersion/bodyMassOverrides/confirm:true to replace selected slot overrides before work; a null slot override returns to its configured trend. Original start identity and derived plans remain pinned.',
          'effectiveLoad':
              'Slots may configure an effectiveMass model with explicit bodyMassFraction, addedMass and assistance components. store effective-load takes database/id; session effective-load takes session. Derived suggested/confirmed-actual estimates preserve raw inputs and do not change progression.',
          'programs':
              'program publish pins workout revisions and may pin a derivedPlan per day; run create takes id/programId/revision/startedAt and a required loop (true repeats the program, false ends the run after its last day) and permits multiple active runs. Pinned day plans are applied automatically at run start. run start selects runId; store finish advances its bound occurrence once. Use run show/list for cursor and currentSessionId; run schedule takes runId and optional count (1–1000) and includeScopes to inspect upcoming days and authored group/repeat context without dates or changes. run upgrade takes runId/expectedVersion/revision/requestId/at/confirm:true and explicitly re-pins the run to another published revision of the same program without moving its cursor; the receipt records the cursor so completed days stay bound to the revision they ran under (a looping run may change any day, including ones already done), the cycle length cannot change once the run has advanced, the current day needs no session yet, and finite runs need enough days. run upgrades lists the durable receipts. run jump takes runId/expectedVersion/dayPath (a day path from run schedule)/requestId/at/confirm:true and moves the run cursor to that program day: back to repeat days (e.g. a Couch to 5K week after a break) or ahead to skip them. Occurrence ordinals, receipts and bound sessions never change; later days continue from the new position, a looping run stays in its current cycle, and a finished finite run reopens. The current day must have no session; retries replay by requestId. run show lists jumps. Day/group/repeat nodes may declare overrides:[{slotId,metric,mode:scale|set,factor|quantity}]; ancestor overrides apply to their days and the nearest declaration wins per slot metric, replacing authored targets exactly before history prefill. Overrides never silently replace an accepted progression-controlled metric; reconcile the track first, and sessions freeze the applied before/after provenance.',
          'analytics':
              'session summary takes session; store summary takes database/id. Optional sumMetrics explicitly selects raw metric sums; warmups are excluded by default. history series/records take sessions and optional runBySession; store series/records read database history. Summaries, series and records support explicit roles selection; series also support metric, exact context, inclusive from/exclusive until and includeActive. Only confirmed results appear; series retain separate role/slot/setup/equipment/run contexts and source versions.',
          'records':
              'history records takes sessions/metric/direction (higher/lower); store records takes database/metric/direction. Optional atActuals filters exact observed quantities; context/from/until/includeWarmups and family selection mirror series (records always use finalized work). Other observed metrics, setup/run/role and timing guidance stay separate. Tracked body-mass/derived-load contexts are excluded pending record policies. Reports include neutral markers, ties, source versions and exclusions; queries do not apply progression. store records includeImported:true (+importNamespace) adds a separate imported section (bodytmi-imported-records/1): completed imported sets only, exact imported contexts with other actuals held fixed, never merged with native records; run/template/slot/setup filters exclude it. includeBlocks:true (+amrapId) adds blocks (bodytmi-block-records/1): confirmed-round scores of finalized AMRAP blocks that ran to their deadline, compared within one run/template/block/frozen loop; partial rounds are reported, not scored.',
          'repeatHistory':
              'repeat-checkpoint series takes database and optional sessionId, runId, metric, from, until, includeWarmups and includeActive. history repeat-series takes checkpoints, sessions and optional runBySession with the same filters. Results retain their repeat definition and session/run context; dates filter session start, and occurrence times are unrecorded. repeat-checkpoint rounds and history repeat-rounds use the same inputs except metric/includeWarmups and include empty attempts plus explicitly reviewed round counts; after-boundary flags record review submission only.',
          'families':
              'family validate takes family{id,name,exercises}. family publish requires database/family/expectedRevision; show takes database/familyId and optional revision; list returns all revisions. Families may overlap and do not imply comparable loads. store series accepts familyId and optional familyRevision; history series accepts a family revision snapshot. Reports pin membership and preserve contextual series.',
          'catalog':
              'Exercises, implementations and equipment accept optional labels{<language tag>:{name?,aliases?}} (canonical tags such as sv or sv-SE, 1–64 locales, up to 32 aliases each); the root name stays the locale-neutral fallback and labels never change identity. catalog search takes database/query and optional locale/kinds(exercise|implementation|equipment)/limit(1–1000, default 50); policy bodytmi-catalog-search/1 searches the latest revisions case-insensitively without accent folding, ranks exact/prefix/word-prefix/substring matches of id, root name, label names and aliases (with locale: only its exact and language-only labels), and returns displayName resolved exact, language, then root. exercise publish requires database/exercise/expectedRevision and stores immutable numbered revisions of exercise{id,name?,notes?,labels?}; show takes database/exerciseId and optional revision; list returns all revisions. implementation publish requires database/implementation/expectedRevision for implementation{id,exerciseId,name?,notes?}; the referenced exercise must already be published, and exerciseId is immutable across revisions; show takes database/implementationId and optional revision; list returns all revisions. Catalog adoption: a slot implementation identifier that matches a published implementation must belong to that slot exercise, and stored publication, archives and backups enforce this; unmatched identifiers stay legacy authoring shorthand. Optional requireCatalog:true on store publish demands every slot exercise and slot implementation-of-that-exercise be published catalog identities and every declared slot equipment a published equipment definition, and on family publish demands every member be a published exercise; missing identities report not_found. Catalog entries never prescribe targets, progression, timing or records, and nothing keys behaviour off an exercise name.',
          'equipment':
              'equipment publish requires database/equipment/expectedRevision for equipment{id,name?,notes?}; gym publish takes gym{id,name?,notes?}; both store immutable numbered revisions and compare-and-set on the per-id head. instance publish takes instance{id,equipmentId,gym?,name?,notes?,scale?,loading?}; the equipment kind and gym must already be published, and equipmentId is immutable across revisions while a gym move, scale or loading change is a new revision. An optional inline scale declares the instance native markings with alternate same-dimension printed labels only; it is display provenance, never an independent load or plate math. An optional loading{components,channel,plates} declares one plate-loading configuration: tare components (bar/collar/handle/tare with explicit include), exactly one channel (one or two sides with required or independent symmetry), and the actual plate denominations and counts at this instance. plate plan takes loading and a mass target and returns only feasible arrangements: exact, or explicitly labeled nearest-lower and nearest-higher choices, never a silent rounding. store plate-plan takes database/instanceId/optional revision/target and evaluates the stored instance configuration; instances without a loading declaration have no plate arithmetic and nothing assumes a bar mass, collars or symmetric sides. Symmetric channels consume plate pairs; independent channels allocate sides as display-only. instance show takes database/instanceId and optional revision; instance list returns all revisions; instance inventory takes database and optional gymId and returns the latest revision of each instance, which is its effective placement. Inventory entries never prescribe targets, progression or records, and slot equipment adoption is pending. An optional instance convention{massBasis,implements?,sides?,repCounting?,notes?} declares how entered mass and repetitions are interpreted: per-implement (mass per implement, 1-64 implements), per-side, assembly-total, added-load or nominal-setting; sides both/left/right and repCounting per-side/combined keep unilateral counting separate. A per-side basis requires a declared symmetric two-sided loading channel and added-load requires declared components; no imaginary bar is ever assumed. Slots may declare the same convention to override the instance default. convention validate takes convention; convention interpret takes convention/mass/optional repetitions/loading and returns exact labeled per-implement, assembly and added masses with explicit unknown reasons plus repetition side expansion, never rewriting entered values or computing totals. store load-convention takes database/instanceId/optional instanceRevision, optional templateId/templateRevision/slotId, optional convention/mass/repetitions and resolves explicitly first, then the slot override, then the instance default, with capability evidence.',
          'sessionLoadContext':
              'Session starts freeze which equipment instance and load entry convention each slot used. store start and run start take optional loadBindings:{slotId:instanceId} (resolved to the latest published instance revision) and loadConventions:{slotId:convention} session overrides; pure session start takes loadInstances with full instance snapshots. Precedence is the session override, then the pinned slot convention, then the instance default, captured once at start; later instance revisions, gym or loading moves never rewrite the session. A bound instance must match the slot declared equipment. Edited, carried or manual targets, results and progression are unaffected. store load-status takes database/id; session load-status takes session/optional instances and reports source or target changes without rewriting the session.',
          'loadArrangements':
              'store arrange takes database/id/expectedVersion/setId/optional arrangement/confirm; session arrange takes session/setId/optional arrangement/confirm. An arrangement {instanceId,channel,plates:[{mass,count}]} records the exact plate stack one completed set used on the session frozen instance revision; counts are totals across the channel and every denomination must be declared stock, split equally on a symmetric channel. Masses are always recomputed exactly from the frozen loading declaration; nothing assumes a bar or tare. An arrangement requires the slot frozen instance binding. Clearing needs arrangement:null with confirm:true. Skipped sets discard arrangements. store arrange-status takes database/id; session arrange-status takes session/optional instances keyed by slot. They report each recorded stack against the current instance head: computed channel and total mass, deterministic side display split, feasibility under current stock, whether a fresh plate plan would choose that stack, convention drift and the descriptive entered-mass relation. Reports never rewrite a recorded stack or its entered mass.',
          'units':
              'Quantities are {value: decimal string, unit}. Units: kg, lb, g, mg and mcg (mass); m, km, cm and mm (distance); s, ms, min, h, d and wk (duration); rep (repetitions); deg (angle, e.g. stretch depth or a joint angle); kJ and kcal (energy); l, dl, cl and ml (volume); ratio and percent (ratio); degC (temperature); mmHg (pressure); bpm (frequency); step (steps); count (a generic tally). Repetitions, steps and tallies are separate whole-number dimensions that never convert into each other. Quantities are never negative. Kitchen measures (msk, tsk, krm) are portions of a food, not units. Conversions are exact and the entered value and unit are kept. A stretch can record depth with an observe objective (deg or cm) and move to its next position with ordinal levels that set a categorical lever, e.g. examples/stretch-depth-practice.json and stretch-depth-rule.json.',
          'measures':
              'A measure defines what is recorded: {id,name,notes?,labels?,kind,dimension?,unit?,scale?,values?,attributes?,summaries?,resolution?}. Kinds: quantity (dimension and preferred unit; counts such as steps are quantities), rating (scale{minimum,maximum,anchors?}), boolean, category (values), text, event, interval. attributes{name:{values?}} are what observations may carry (site, side, state, method, device, context...); each combination is its own series and series never merge silently. summaries are a subset the kind permits of mean, sum, min, max, last, count (default last and count; summing must be declared). resolution{policy latest|trend|extrapolated, staleAfterDays?, and for extrapolated windowDays 90, minPoints 4, minSpanDays 28, maxAheadDays 30 by default}; trend applies to mass and ratio quantities. measure validate takes measure; measure builtins lists the shipped body catalog: body-mass, body-fat (method bio-impedance/navy/caliper/dexa/other), height, circumference (site/side/state), skinfold (site/side) and steps.',
          'measurements':
              'measure define takes database/measure/expectedRevision and publishes a custom measure revision (built-in ids are reserved; kind and dimension never change; a revision must still accept every stored observation of it). measure show takes measureId and optional revision (built-ins report builtIn:true); measure list returns built-ins and the latest custom revisions. An observation is {id, measure, value?, observedAt (with offset) or date (YYYY-MM-DD), attributes?, source?, notes?, import?{namespace,sourceId}}; the value fits the measure kind (quantity {value,unit}, rating integer, boolean, category or text string, none for an event, {end} for an interval). observation record takes observation (version 1); observation update takes observation/expectedVersion and writes version expectedVersion+1; identical retries return the stored record. An observation never changes measure, a deleted identity is never reused, and an import identity names one observation. observation delete takes id/expectedVersion/confirm:true and keeps a deletion marker with the last content. observation show takes id; observation list takes optional measure, from (inclusive) and until (exclusive) local dates, attributes and includeDeleted, sorted by local date. Body-mass observations (measure body-mass, attribute context, an instant) are the same records the mass commands use. observation resolve takes database/measure/asOf (an instant with offset) and optional attributes (the series: exactly this attribute combination), resolution (a policy object replacing the measure default) and dailyMode mean|replace (trend). Policy bodytmi-observation-resolution/1 returns status resolved or unavailable (with reason; never zero), used (latest, trend or extrapolated), estimate, value, observedOn, ageDays, stale, sourceCount and a SHA-256 fingerprint over every eligible observation. latest is the most recent observation in force; trend (mass and ratio quantities) is the body-mass trend algorithm; extrapolated fits a least-squares line to the windowDays before the last observation, needs minPoints spanning minSpanDays (else falls back to latest with fallbackReason), holds at maxAheadDays past the last point (capped) and reports slopePerDay, points and evaluatedOn. Date-only observations count from their date. Without a request resolution, the stored series policy applies, then the measure-wide one, then the measure default; policySource says which (request, series, measure or default). measure policy takes database/measure/resolution (null clears)/expectedRevision and optional attributes (a series; omit for measure-wide) and records a numbered revision; the policy must fit the measure. measure policies takes database and optional measure.',
          'calculations':
              'calc list returns every calculation with its id (bodytmi-calc/<name>/<version>), formula, source, inputs and reference policy. calc evaluate takes calculation and inputs: quantities as {value,unit}, sex as male or female, age as whole years. The result echoes every input, and is unavailable naming what is missing; values round once to nine fractional digits. Calculations: bmi (WHO adult classes), waist-to-height (NICE bands), waist-to-hip and waist-risk (WHO 2008, by sex), navy-body-fat (Hodgdon & Beckett; men navel/neck/height, women waist/hip/neck/height), jackson-pollock-3 and -7 (Jackson & Pollock 1978, Jackson, Pollock & Ward 1980, Siri), fat-mass, fat-free-mass (not muscle mass), ffmi and normalized-ffmi (Kouri et al. 1995), target-mass and walking-energy. Categories describe, never diagnose.',
          'seriesQueries':
              'One series is a measure plus its exact attributes (omit attributes for none); observations are placed by local date, deleted ones excluded, nothing invented for empty days. Ranges are local dates from (inclusive) and until (exclusive). Summaries, each only if the measure declares it: count (observations), sum (exact; intervals in seconds), mean (mean of daily means: each day with data counts once, days without data are not zero; exact, rounded once to nine digits), min, max, last. Quantities are reported in the canonical unit (kg, m, ratio, step...). series query takes database/measure/attributes?/from/until/summary and optional bucket none (default; every observation with its entered value, version and canonical value)|day|week|month and weekStart 1 (Monday, default) to 7; buckets are clipped to the range and carry observations, coverage {daysWithData, days} and value (null when empty). Policy bodytmi-series-query/1 also returns overall and a fingerprint. series compare takes database/measure/attributes?/a{from,until}/b{from,until}/summary and returns both periods with coverage and the signed change from a to b (bodytmi-series-compare/1). series slope takes database/measure/attributes?/from/until and optional per (days, default 7) and fits a least-squares line through the daily means: slope per period, points (days with data), first, last, spanDays; unavailable with fewer than two days (bodytmi-series-slope/1, an estimate). More than 10000 points or buckets is an error, never truncation.',
          'food':
              'Foods and the diary (stage 3). Nutrients use a fixed vocabulary keyed to EuroFIR codes (energy in kcal as on labels; carbohydrate is available carbohydrate; fibre separate). food validate takes food (pure). A base food is {id,name,labels?,notes?,source?{kind label|dataset|lookup|other,...},kind:base,basis:100g|100ml,nutrients{id:quantity},valueTypes?,density?{mass,volume},portions?[{id,name?,amount}]}; values are as printed; a per-100 g food is logged by volume (or a per-100 ml one by mass) only with a declared density. A composite is {id,name,kind:composite,components[{food{id,revision},amount}],batch?{finalMass,portions?},portions?}: it pins component revisions, nests to any depth and is rejected when a food would contain itself. Amounts are a mass or volume quantity or {portion,count}; composites take portion whole (one of it), portion portion (one of a batch\'s declared portions) or a mass (needs a known total mass: the batch final mass, else the sum of component masses). food publish takes database/food/expectedRevision (compare-and-set; every change is a new immutable revision; logged entries keep theirs). food show takes foodId/revision?/nutrients? and returns per 100 g/ml, or whole, per100g and perPortion for composites. food list returns latest revisions. food nutrition takes food{id,revision?}/amount/nutrients?. food dependents takes foodId and lists composites whose latest revision pins an older revision of it; food follow takes foodId/expectedRevision/components? and publishes the composite with those components (default all outdated) pinned to their latest revisions. Nothing follows automatically. Totals count items (base foods and quick entries reached): a nutrient is known when every item declares it, partial with knownItems, unavailable (null, never zero) when none does. sodium is the element (mg) and salt is sodium chloride (g, as on Swedish labels); an item declaring only one gets the other from the EU label definition salt = sodium × 2.5, counted as derivedItems. nutrients is omitted (energy, protein, carbohydrate, fat, fibre), a list, or \"all\". food dataset-info/dataset-search(query,limit?)/dataset-show(number,nutrients?) read a packaged bodytmi-food-dataset/1 file (dataset: path; gzip allowed) without a database. The shipped data/food/slv.json.gz is the Swedish Food Agency database (Livsmedelsverket, CC BY 4.0; values per 100 g edible part as published). food lookup (opt-in, online, no database) takes barcode and optional foodId/endpoint and asks Open Food Facts for that product, sending only the barcode with a generic client name; it returns an unsaved base food (id off-<barcode>, source lookup with the product URL and the ODbL notice) from the declared per-100 g or per-100 ml values only (modifiers such as < kept as value types; per-serving products are refused; vitamin A, E, folate, niacin, alcohol and Open Food Facts estimates are skipped). Review it and save it with food publish. food search-online takes query and optional limit (1–50)/endpoint and lists matching barcodes. Network failures exit 4. food adopt takes database/dataset/number/foodId? and copies the dataset food into the profile (id slv-<number>), publishing a revision only when it changed and keeping your own portions and density. diary add takes entry{id,at (with offset),date?,meal?,notes?, food{id,revision?}+amount | quick{nutrient:quantity}}; without revision the latest is pinned. The diary date is the local date of at, or the day before when before the day start (default 04:00; diary settings, diary set-day-start takes dayStart HH:MM 00:00–12:00 and expectedRevision); an explicit date may be either. diary update takes id/expectedVersion/entry (version+1); diary delete takes id/expectedVersion/confirm:true; diary show takes id. diary water takes id/at/amount/meal? and logs the water food (created on first use, density 1 g/ml declared). diary repeat takes from/to/idPrefix/meal? and copies entries at the same local times with the same pinned revisions. diary mark takes date/status complete|partial|unmarked; without a mark a day with entries is partial and one without is unlogged; complete with no entries means nothing was eaten. diary day takes date/nutrients? and returns entries, status, totals and budget (policy bodytmi-diary-budget/1: each goal of the diet-run day in force with target, eaten and remaining or over; ranges report relation and distance to both bounds; a partly known intake makes remaining an upper bound, bound atMost). diary report takes from/until/nutrients? (a list) and returns daily totals and averages over complete days and over logged days, each stating how many days contribute; a day whose nutrient is only partly known does not contribute to that nutrient. diary adherence takes from/until/tolerancePercent? (policy bodytmi-diary-adherence/1): over complete days with a plan day, each goal\'s mean eaten, mean target and mean deviation, ranges counted below/within/above, single values only with a tolerance. energy calibrate takes database/from/until (7–366 days) and optional context/minimumDays (default 14): policy bodytmi-energy-calibration/1 returns mean intake over complete diary days minus the energy of the trend mass change (Forbes lean share, Hall densities) as calibrated maintenance, compared with the formula in force (band agrees within 200 kcal, disagrees from 300, after McDonald IMF ch. 14), or insufficient with reasons (too few complete days, fewer than two weekdays and one weekend day, items without energy, missing mass or fat-free mass). It writes nothing; adopt it with energy method {formula: manual}. diary reference takes database/from/until (1–366 days) and optional context: policy bodytmi-reference/nnr-2023/1 compares mean intake over complete diary days with the adult Nordic Nutrition Recommendations 2023 (by profile sex and age; pregnancy, lactation and children are not modelled): RI and AI (Tables 12–15), thiamin and niacin per MJ eaten, protein 0.83 g/kg trend body mass (Table 11), sodium (the element) limit 2.3 g and the equivalent salt limit 5.75 g (Table 16), upper levels (Table 21; magnesium, folic acid and niacin ULs apply to supplement forms only and are listed under notCompared), and Box 2 energy shares (protein 10–20, fat 25–40, MUFA 10–20, PUFA 5–10, saturated <10, carbohydrate incl. fibre 45–60, free sugars <10 E%; 17/37/17/8 kJ/g) plus fibre at least 3 g/MJ. Relations are meets/below, within/above or unknown; a day whose items do not all declare a nutrient is left out for it. Reference values are separate from your plan targets and change nothing.',
          'sleep':
              'Sleep and daylight (stage 4). profile set accepts location{latitude,longitude (decimal strings),timeZone (IANA, e.g. Europe/Stockholm)}. A sleep is {id,kind main|nap,asleepAt or bedAt+latencyMinutes,wakeAt,bedAt?,outOfBedAt?,awakenings?,awakeMinutes?,quality? 1–5,approximate?,notes?}, every instant with its offset; the night belongs to the local date of wakeAt. Sleep period = onset to wake; asleep needs awakeMinutes; time in bed needs bedAt and outOfBedAt; nothing is assumed. Records never overlap. sleep record takes sleep; sleep update takes id/expectedVersion/sleep; sleep delete takes id/expectedVersion/confirm:true; sleep show takes id; sleep list takes optional from/until (wake dates). sleep mark takes date/status complete|unmarked: complete means every sleep overlapping that local day is logged, so time outside records was awake. sleep schedule takes schedule{from,sleepAt,wakeAt (HH:MM),days?[{weekdays 1–7,sleepAt,wakeAt}],commitments?[{id,label,weekdays,start,end same day}]}/expectedRevision (the latest from on or before a date is in force); sleep schedules lists them. sun times (pure) takes location/from/days? and sleep sun takes from/days? with the profile location: policy bodytmi-solar/1, NOAA solar equations (checked against the US Naval Observatory for Stockholm and Tromsø to the minute), per local day the rise/set crossings of the sun (−0.833°), civil (−6°), nautical (−12°) and astronomical (−18°) thresholds, or state above/below all day, minutesAbove, solar noon and maximum elevation. sleep stats takes from/until (wake dates, ≤366 days): policy bodytmi-sleep-stats/1, missing nights listed as unknown (never awake), means of sleep period, asleep, in bed, awakenings and quality over logged nights, circular mean and spread of local onset, wake and midpoint, nap count, and regularity bodytmi-sri-known-pairs/1 (Sleep Regularity Index over pairs of consecutive days both marked complete, minute by minute on the profile time zone clock; needs a profile location). sleep plan-view takes from/until (≤62 days): policy bodytmi-sleep-plan-view/1, per night the actual sleep, naps, desired times and signed deviations in minutes, commitments overlapping the sleep, caffeine from the food diary in the 24 h before onset (total, last intake, items without caffeine) and the day\'s sun and civil twilight. Format bodytmi-sleep-import/1: {format, source{namespace,app?,version?,exportedAt?}, sleeps[{sourceId,id?,...sleep fields}]}; sleep import-validate (pure), sleep import-preview and sleep import-apply (confirm:true, onChanged reject|update) like the observation import; overlaps with other records are conflicts. The app does not estimate the internal body clock.',
          'practices':
              'Journal, practices and activity (stage 5). Journal measures are built in and used with observation record/list/resolve: symptom (rating 0–10, attribute name), pain (rating 0–10, attributes site, side left|right|both, impact none|minor|limits-activity|prevents-activity), illness (interval {end}, attribute name), mood and energy-level (ratings 0–10). They are plain self-ratings, not validated questionnaires. practice define takes practice{id,name,kind?,notes?,source?,durationSeconds?,preparationSeconds?,phases? (a tempo plan {phases:[{id,milliseconds}]}, e.g. inhale/hold/exhale),ratings?[{id,label,minimum,maximum,when before|after|both}]}/expectedRevision; practice show takes practiceId/revision?; practice list. practice start takes id/practiceId/revision?/at/before? and creates the session with a paused clock (open-ended without a duration). The clock is an ordinary timing activity owned by the session (id practice-<id>), so the single foreground clock rule covers training and practice together. practice run takes id/runForMilliseconds?/stream? and runs it in the foreground (stream:true emits NDJSON phase cues; Ctrl-C pauses); a killed process leaves the clock running and practice recover (id/at/adjustmentMilliseconds?) freezes it or applies an explicit adjustment. practice end takes id/at and ends the clock early (open-ended practices always end this way). Reaching the duration ends the clock but does not complete the session: practice confirm takes id/expectedVersion/at/after?/notes? and records the clock time. practice abandon takes id/expectedVersion/confirm:true; practice log takes id/practiceId/at/milliseconds and optional ratings/notes for a session done without the timer. practice session takes id (with its clock and requiresRecovery); practice sessions takes optional from/until. activity record takes activity{id,kind (walk, run, outdoor, sedentary... any identifier),start,end (instants, under 24 h),distance?,steps?,outdoor?,countsToward?[category ids, each once],approximate?,notes?,track?[{at,latitude,longitude,elevation?}]}; activity update takes id/expectedVersion/activity; activity delete takes id/expectedVersion/confirm:true; activity show, activity list (from?/until?, start dates; tracks shown as point count and haversine distance). activity summary takes from/until: policy bodytmi-activity-summary/1, per day minutes and counts per kind and per category (each activity once per category it names, so one walk counts toward movement and outdoor-light once each), outdoor and sedentary minutes. Activity never adds energy to the intake budget. Format bodytmi-activity-import/1 {format,source{namespace,...},activities[{sourceId,id?,...activity fields}]}: activity import-validate (pure), import-preview, import-apply (confirm:true, onChanged reject|update), idempotent; absent imported activities are kept.',
          'goals':
              'Goals, routines, trials and reviews (stage 6). A daily metric (policy bodytmi-daily-metric/1) is one value per local date: {source observation, measure, attributes?, summary mean|last|sum|min|max|count or resolved:true}, {source sleep, field asleepMinutes|sleepPeriodMinutes|inBedMinutes|quality|awakenings|onsetClock|wakeClock|midpointClock} (main sleep ending that day; clock fields in minutes after local midnight, before midnight negative), {source diary, nutrient, field total|lastIntakeClock} (complete days whose items all declare it; none on a complete day without the nutrient), {source activity, category or kind, field minutes|count}, {source practice, practiceId?, field minutes|count}, {source training, field sessions}, {source budget, goal} (eaten minus the plan target on complete plan days); optional label. A day without data is unknown, never zero. metric evaluate takes metric/from/until. goal save takes goal{id,name,metric,aggregate mean|sum|min|max|latest|daysMet,target{relation atMost|atLeast value | within minimum maximum, decimal strings},from,until?,status active|achieved|abandoned (default active),notes?}/expectedVersion (0 creates); goal show, goal list (with body plan targets as plan goals: a body plan is a goal with a programme, held by the plan record), goal progress takes id/asOf (bodytmi-goal-progress/1: met, not-met, unknown or, for daysMet, days met of known days). routine save takes routine{id,name,action{kind activity+category | practice+practiceId | observation+measure | check},schedule{weekdays?,at HH:MM | relative{anchor wake|bedtime|meal (+meal label)|workout, offsetMinutes},windowMinutes?},from,until?,notes?}/expectedVersion; routine list; routine check takes routineId/date/at/undo? for check routines. today show takes date (bodytmi-today/1): active routines with due time (clock, or the anchor actual if logged else planned from the sleep schedule) and status done with evidence or not-logged, never missed, plus active goals with progress. No streaks. trial save takes trial{id,question,action{description,metric?,target?},baseline{from,until},trial{from,until} (not before the baseline ends),outcomes[metrics]}/expectedVersion; trial show, trial list; trial report takes id (bodytmi-trial-report/1: each outcome described over both periods with known days, mean, median, sd, min, max, and mean/median differences; action adherence days met, not met and unknown, where none meets an atMost target); descriptive only, not proof of an effect. trial conclude takes id/expectedVersion/decision keep|adjust|stop|unclear/at/notes?. review save takes review{id,name,metrics,notes?}/expectedVersion; review list; review run takes id/from/until (bodytmi-saved-review/1: each metric\'s days and summary).',
          'observationImport':
              'Format bodytmi-observation-import/1 (neutral; converters for particular apps are separate tools): {format, source:{namespace (identifier <=64), app?, version?, exportedAt?}, observations:[1-100000 of {sourceId (1-256 chars, unique), id?, measure, value?, observedAt or date, attributes?, source?, notes?}]}. Entries are observations as in observation record, keyed by namespace+sourceId; without id the stored id is <namespace>-<24 hex of SHA-256 of namespace and sourceId>. Entered units, offsets and date-only entries are kept. observation import-validate (pure) takes document. observation import-preview takes database/document; observation import-apply takes database/document/confirm:true and optional onChanged reject (default)|update, writing everything or nothing. Each entry is new, unchanged, changed (version+1 only with onChanged:update), deleted (deleted here earlier; stays deleted) or conflict (its id belongs to another record; blocks apply). Importing the same document again writes nothing. Observations of the namespace missing from the document are listed as absent and kept; delete them with observation delete.',
          'energy':
              'Maintenance energy is one named method you choose (F4). energy method takes database/from (YYYY-MM-DD)/method/expectedRevision; the method in force on a date is the latest from on or before it. Methods: {formula: mifflin-st-jeor|katch-mcardle, pal (1-3), adjustment? (-0.5..0.5)} = resting energy (Mifflin: 10 kg + 6.25 cm - 5 age + 5 male / -161 female; Katch-McArdle: 370 + 21.6 fat-free kg) x pal x (1 + adjustment); {formula: mcdonald-rfl-maintenance, activity: sedentary|light|moderate|very|extreme, calPerLb within 10-11|11-12|12-13|14-15|18-19} = body lb x calPerLb (Rapid Fat Loss Handbook ch. 14); {formula: mcdonald-imf-tdee, activity: inactive 1.1|light 1.2|moderate 1.3|high 1.5, exercise?: [{kind: low-aerobic 0.2|medium-aerobic 0.3|high-aerobic 0.4|hiit 0.3|moderate-weights 0.1|high-weights 0.2 per hour, hours}]} = body lb x BMR cal/lb by category (10/9/8) x (activity + exercise) for the day described (IMF ch. 14); {formula: manual, energy}. 1 lb = 0.45359237 kg exactly. energy methods lists selections. energy estimate takes database/asOf and optional context and method (evaluate another method without storing); policy bodytmi-energy-estimate/1 returns the inputs from the body report (mass, height, fat-free mass, body fat with its source, sex, age, diet category) and maintenance {status, value kcal, factors, formula, source} or unavailable naming what is missing. Diet category (bodytmi-diet-category/1): men < 15.5 % 1, < 25.5 % 2, else 3; women < 24.5 %, < 34.5 %; from the selected body-fat source.',
          'plans':
              'The body plan is one programme (or your own cycle) as the diet run, one at a time. plan preview takes database/startDate/asOf and either programme/choices or cycleId/cycleRevision (optional context) and returns the guide plus the companion changes offered, each with what it would replace: steps (use the plan day types step goals while active; offered when any day type has steps), pauseRun per active training run (ERFL), recommendedTraining (RFL, information only). Nothing is written. plan activate takes planId/startDate/asOf/requestId, the programme/choices or cycle, and optional companions {steps: bool, pauseRuns: [runIds]} and namedDiet (a label from diet references): it applies the programme as day types and cycle named after planId, starts diet run planId (frozen inputs and targets) and applies only the named companions, all in one transaction; a retry with the same requestId returns the stored plan. plan end takes planId/date (exclusive)/expectedVersion/confirm:true and optional resumeRuns: it ends the diet run and resumes each named run the plan paused unless it was changed since (left alone and reported). plan target takes planId/expectedVersion/target ({measure: mass|bodyFat, relation: atMost|atLeast, value: a mass or a percentage}, or null to clear); plan review then reports the target as reached, not-reached or unknown (trend mass, or body fat from the selected source) and, once reached, proposes ending the plan from the next day. Nothing ends on its own. plan show takes planId; plan list. stepgoal set takes from/steps (null clears)/expectedRevision for the standalone daily step goal; stepgoal list; stepgoal show takes date and returns the goal in force: the plan day type steps when the plan took over steps, else the standalone goal, with its source.',
          'reviews':
              'plan review takes database/planId/asOf and optional policy (bodytmi-plan-review/1 default, or mcdonald-moderate/1 for Normal plans) and performanceDropping. It compares the 21-day mass trend with the simulation of the same days under the plan (needs 21 days since the plan start or its latest change), the current inputs with the frozen targets, the category with the plan category, and whether a finite cycle is over, and records at most one pending proposal per kind: lower-intake (-100 kcal/day when the trend lost under 25 % of the planned loss; moderate policy: -10 % under 1 lb/week, +10 % at 2+ lb/week with performanceDropping), recompute (an energy or protein target would move more than 5 %), category (the selected body-fat source crossed a boundary), end (the finite cycle is over), break (a Normal plan ran its handbook ch. 15 stint: category 1 4, 2 6, 3 12 weeks since its start or last break; accepting makes the next 14 days <plan>-break days at maintenance) and insert-rfl (the trend is 2 % above the plan baseline mass and the cycle has an RFL day: accepting makes 3 of the next 7 days RFL days, IMF ch. 34). Energy changes apply only to day types whose energy is a single value, not a macro sum (RFL days are their own floor), and are not proposed when a goal would fall below zero. plan proposals takes optional planId. plan accept takes proposalId/from (and choices for a category change that needs new choices): it changes the plan once from that date as a dated change of the diet run (earlier dates keep their targets), or ends the plan; accepting again returns it. plan decline takes proposalId.',
          'programmes':
              'Four built-in diet programmes (programme list shows source, choices and recommendations): normal (deficit {kcal}|{percent}, default 500 kcal; proteinPerKg default 1.8), rfl (Rapid Fat Loss Handbook: activity inactive|aerobic|weights, carbohydrate/fat g default 20/20, breakActivity, breakDays 7-14; category 1 dietDays 11-12, refeedDays 2-3, refeedCarbohydratePerKg 12-16; category 2 dietWeeks 2-6, refeedCarbohydratePerLb 1.5-3; category 3 dietWeeks 6-12), erfl (Extreme Rapid Fat Loss: walking {steps}|{distanceKm}|{hours,speedKmh}, afterDays 1-28, carbohydrate/fat default 0; protein from the aerobic-only column) and imf (Intermittent Modified Fasting: activity none|aerobic|weights, pattern 6:1|5:2|4:3|3:4|2:5|1:6|3:11|1:13, arrangement as M/R letters, fatPerLb 0.25-0.5, maintenanceAdjustment -0.1..0.1, carbohydrate/fat default 20/20, fullVolumeTrainingDays for the warning). Book ranges have no silent default. programme guide takes database/programme/choices/asOf and optional context, method and simulateDays; policy bodytmi-programme-guide/1 returns the category (from the selected body-fat source), day types with resolved goals, schedule, cycle, recommendation, warnings, the book estimate (deficit / 3,500 kcal per lb, days without an energy goal at maintenance, ERFL walking at 0.75 kcal per kg per km), inputs, and the simulation; unavailable names missing inputs or choices. programme compare takes choices {programme: choices} and asOf (and simulateDays) and returns all four guides. programme apply takes programme/choices/asOf/prefix and publishes day types <prefix>-... and cycle <prefix> (unchanged ones are reused) for diet start. cycle guide takes cycleId/revision/asOf and optional startDate/context/method/simulateDays: the same guide for your own cycle. The simulation (bodytmi-energy-balance-simulation/1, an estimate, 1-730 days) recomputes expenditure each day from the projected body with the maintenance method, splits each change into fat and lean by the Forbes curve (lean share 10.4/(10.4 + fat kg)) with 39.5 and 7.6 MJ/kg (Hall 2008), and lists its limits.',
          'diets':
              'diet references (pure) lists named diets for information only (D21): description and source; they never filter or score foods. A day type is {id, name, notes?, goals:{energy?, protein?, carbohydrate?, fat?, fibre?}, steps?}. Each goal is {fixed: quantity}, {minimum, maximum}, {basis: maintenance, factor?} (energy only), {basis: mass|fat-free-mass, perLb|perKg} (grams, or kcal for energy, per lb or kg of it), each optionally with add/subtract quantities, {remainder:true} (carbohydrate or fat: what energy leaves after the other two at 4/4/9 kcal per g) or {sum:true} (energy = 4 protein + 4 carbohydrate + 9 fat). Energy goals resolve in kcal, macros in g. daytype publish takes database/dayType/expectedRevision (immutable numbered revisions; identical replay returns the head); daytype show takes dayTypeId/revision?; daytype list; daytype resolve takes dayTypeId/asOf and optional revision/context/method and previews the goals from current inputs (maintenance by the method in force, trend mass, fat-free mass from the selected body-fat source). A diet cycle is {id, name, notes?, loop, days:[nodes]} with nodes {type:day, dayType:{id,revision}, label?}, {type:group, label?, days} and {type:repeat, count, label?, days}, at most 3660 days; cycle publish/show/list as day types (pinned day types must exist). diet start takes runId/cycleId/cycleRevision/startDate/asOf/requestId and optional context: it freezes the inputs at asOf and the targets of every day type the cycle uses (refused, naming them, if any goal is unavailable). Only one run is open at a time: end the previous one first. Day n of a run is fixed by the calendar from startDate, logged or not (F21); a finite cycle ends after its days. diet override takes runId/date/dayType ({id,revision}, or null to remove)/reason/expectedVersion and replaces only that date; diet move takes runId/from/to/reason/expectedVersion and swaps the two dates day types (e.g. a maintenance day moved to Saturday) without shifting later days; diet end takes runId/date (exclusive)/expectedVersion/confirm:true. diet show takes runId; diet list. diet schedule takes from and optional days (1-366, default 14) and runId and returns policy bodytmi-diet-schedule/1: each date with its run, day type and name, source cycle or override (with reason), cycleDay, label/path, the frozen goals, steps and notes.',
          'body':
              'profile show takes database; profile set takes database/profile{sex? male|female, birthDate? YYYY-MM-DD, stepLength? distance}/expectedRevision (facts are formula inputs only). body source takes database/from (YYYY-MM-DD)/source/expectedRevision: source is {kind:calculation, calculation: navy-body-fat|jackson-pollock-3|jackson-pollock-7}, {kind:series, method: bio-impedance|dexa|caliper|other} or {kind:mean, components:[2-8 of those]}; the selection in force on a date is the latest from on or before it, else Navy. body sources lists selections. body report takes database/asOf and optional context (body mass, default health) and returns policy bodytmi-body-report/1: every body measure resolved under its series policy (mass, height, waist/navel/hip/neck circumferences, skinfold sites, body fat per method, steps) and every calculation (BMI, waist ratios, Navy, Jackson–Pollock 3 and 7, fat mass, fat-free mass, FFMI) with each input\'s observedOn, ageDays, stale, used policy and source. Skinfold estimates need every site measured on the same day and use age on that day; a mean body-fat source is unavailable unless every component is.',
          'sessionTimes':
              'Session and run timestamps keep the UTC offset they were entered with: store start, run start, run create, store finish and session start/finish write startedAt/finishedAt in that local time (Z for UTC), and a retried start with another offset conflicts. Instants still order sessions and measure elapsed time. store finish and session finish accept optional endedAt (between start and finish) when the session is finalized later than training stopped, such as an evening workout closed the next morning; summaries then report endedAt and measure elapsed time to it. endedAt is written in the finish offset.',
          'unplannedSets':
              'store add-set takes database/id/expectedVersion/slotId/actuals and optional role (default warmup)/observations/settings, and logs a completed set that was not in the plan, such as a starting-weight ramp or an extra back-off set. It is stored as extra-<n> (strictly increasing, gaps after removal) with the next ordinal of its slot and role and the slot default settings. Unplanned sets count in summaries (flagged unplanned), series, records and graph history, but never in progression, prefill or guided traversal. store complete and store annotate correct them; store remove-set takes database/id/expectedVersion/setId/confirm:true and removes one (planned sets are skipped, never removed).',
          'catalogImport':
              'Catalog files use format bodytmi-catalog-import/1: {format, source{name,version?,notes?}, exercises?, implementations?, equipment?, blueprints?}, each entry in its ordinary JSON shape and unique per kind. The shipped starter catalog is data/starter-catalog.json (well-established exercises, implementations and gym equipment with Swedish labels, plus barbell and weight-stack equipment blueprints; names and shapes only). catalog validate takes document. catalog preview takes database/document and reports new, unchanged and changed entries (policy bodytmi-catalog-import-plan/1). catalog apply also takes confirm:true and optional onChanged reject (default: any changed entry refuses the whole file) or update (publishes the next revision). Applying is atomic and idempotent and never deletes entries missing from the file.',
          'blueprints':
              'A blueprint is a programme or workout with open choices; it can never be started itself. blueprint validate takes blueprint{id,name,notes?,source?,choices?,workouts{key:workout without id},program?,presets?{key:preset without id}}. Choices are {id,kind,label?,notes?,options?,family?,dimension?,minimum?,maximum?,default?} with kind exercise/implementation/equipment/gym (identifier, optionally from options, an exercise optionally from a family), setting (one of options), quantity (dimension, inclusive bounds), number (decimal string, decimal-string bounds), integer (integer bounds) or plates ([{mass,count}], 1-64 distinct denominations). Equipment blueprints add instances{key:equipment instance without id}, published as <name>-<key> (e.g. an Olympic barbell with bar mass and plates open, a selectorized stack with first weight, step and pin count open); {"\$value":choice}/{"\$unit":choice} give a quantity choice\'s entered value string or unit. A blueprint needs a workout or an instance. Placeholders are single-key objects anywhere in the templates: {"\$choice":id}; {"\$scale":{choice,factor,step?,rounding?}} (a quantity choice times an exact factor, rounded to a multiple of step in its entered unit: down, up or nearest half up); {"\$workoutId":key}/{"\$workoutRevision":key}; {"\$presetId":key}. Every choice must be used. blueprint publish takes database/blueprint/expectedRevision (an identical blueprint replays the head); blueprint show takes blueprintId/revision?; blueprint list. blueprint preview takes database/blueprintId/revision/name/choices and returns the filled, validated documents (policy bodytmi-blueprint-fill/1) without writing. blueprint instantiate also takes expectedInstance and optional requireCatalog: in one transaction it publishes workouts <name>-<key>, presets <name>-<key> and programme <name> through the ordinary validators and records receipt {blueprint, blueprintRevision, choices (with defaults), workouts, programRevision, presets}. expectedInstance 0 needs every identity unused; filling in again (expectedInstance = latest receipt) publishes the next revision of each and conflicts if one was edited since; an identical retry returns the receipt. Runs keep their pinned revisions until run upgrade. blueprint instances takes database and optional name.',
          'gyms':
              'Equipment definitions may declare interchangeable:true (barbells, plates, dumbbells: results on one instance compare with another); omitted means not interchangeable (most machines). store gym-check takes database/templateId/revision/gym and optional loadBindings/unboundSlots and returns policy bodytmi-gym-binding/1: per slot explicit, bound (the gym\'s only instance of the slot equipment), unbound, missing, ambiguous (with candidates) or none, and ready. store start and run start take optional gym (a published gym) and unboundSlots (needs gym): explicit loadBindings win, every other equipment slot binds the gym\'s single instance, and a missing or ambiguous slot is a conflict before anything is stored. The session records gym; retries repeat gym, explicit bindings and unbound slots. Prefill skips results on a different non-interchangeable instance. progression propose refuses (validation) a session whose slot binding is another non-interchangeable instance than the one the track last progressed on: the visit is neutral, never a failure, unless countOtherInstance:true counts it (stored on the decision; the track then continues from that instance). Sets marked with store perform-on are explicit per-set choices and are not refused. session start takes an optional gym label. gym publish also takes optional preferred{equipmentId:instanceId} (an instance placed at that gym, bound when the gym has several of that kind: status preferred) and setupNotes{exerciseId:note}; a start at the gym freezes the note per slot of that exercise as session gymSetupNotes (display only, never a history context). run create takes optional gym; run gym takes database/runId/expectedVersion/gym (null clears). run start uses the run default gym unless the request names gym (null starts without one). store series and store records take optional gym to count only sessions started there (not with includeImported).',
          'performedOn':
              'store perform-on takes database/id/expectedVersion/setId/instanceId (null clears, with confirm:true) and optional applyToRemaining to record that a set, and the later untouched sets of its slot and role, are performed on another published instance of the slot equipment, e.g. the kg machine when the lb one is taken. The latest instance revision is frozen on the set; targets keep their own unit. The response lists, per set and metric, the nearest settings on that instance to each target (both neighbours on an exact tie). Progression counts a controlled actual equal to such a nearest setting on the instance used (the set\'s performedOn, else the session binding) as following the target, reports it as followedSettings, and keeps progressing in the track\'s unit; an available target must still be met exactly. A plate arrangement on such a set belongs to its performedOn instance. Optional unavailablePlates [{mass,count}] records declared plates that were missing (e.g. micro plates left at home); they must be in the instance stock with at least one plate remaining, nearest settings are judged on the remaining stock, and a recorded stack may not use them.',
          'locale':
              'Presentation only (policy bodytmi-locale/1); canonical records and all other JSON stay locale independent, and a locale never implies a unit preference. Every locale command takes locale (BCP 47, e.g. sv-SE), resolved exactly, then by language, then the en root, reported as match exact/language/root. locale info returns decimal/group separators, minus sign, zero digit, grouping sizes, ISO firstWeekday (1 Monday ... 7 Sunday), weekendDays, hourCycle and message catalog. locale format-number takes a decimal string value and optional grouping (default true) and minimumFractionDigits (zero padding only; digits are never rounded). locale parse-number takes text and optional allowGrouping: locale or ASCII digits, the locale minus sign or -, exactly the locale decimal separator, and group separators only when allowed and at locale grouping positions; it returns a canonical decimal string. locale format-date takes value (timestamp with offset, or YYYY-MM-DD for style date), style date/time/datetime and hourCycle locale/h12/h24, formatting the recorded wall clock, never the process timezone. locale format-duration takes whole milliseconds and style clock (m:ss or h:mm:ss) or units; locale parse-duration accepts only m:ss, h:mm:ss or explicit descending units (h, min/m, s with optional fraction, ms) and rejects bare numbers, returning milliseconds plus a seconds quantity. locale message takes a stable key and args (count for plural keys) and reports the catalog used and any fallback to en.',
          'historyImport':
              'import validate takes document in format bodytmi-history-import/1: source{namespace,app?,version?,exportedAt?}, sessions[{sourceId,date (YYYY-MM-DD) xor startedAt (timestamp with offset),finishedAt?,timezone?,name?,notes?,raw?,exercises[{sourceId,order,name,exerciseId?,implementationId?,equipment?,convention?,notes?,raw?,sets[{sourceId,ordinal,role work/warmup/backoff/drop/unknown,status completed/skipped/interrupted/unknown,actuals?,targets?,observations?,raw?}]}]}] and measurements[{id,sourceId,context,observedAt,mass,notes?}]. Every quantity names its unit; raw preserves unresolved source fields (integers or strings only). import preview takes database/document and reports new/unchanged/changed/conflict per record plus absent records, without writing. import apply additionally takes importedAt, confirm:true and optional onChanged reject (default) or update; it writes the whole plan in one transaction or nothing, reuses source identities so identical reimports are no-ops, and never deletes records absent from a later export. Imported measurements become body-mass observations in their explicit context with source provenance; another source or deleted identity conflicts. Imported sessions pin no workout revision and never feed prefill, progression, records or program cursors. import list takes database and optional namespace; import show takes database/namespace/sourceId; import delete takes database/namespace/sourceId/expectedVersion/confirm:true. import series takes database/metric and optional namespace, exerciseId, exerciseName, roles (default all but warmup), from inclusive and until exclusive calendar dates; contexts keep namespace, catalog mapping or exact source name, implementation, equipment, convention, role and entered unit separate, and date-only sessions are never given an invented time. store series optionally takes includeImported:true and importNamespace to add a separate imported block (policy bodytmi-imported-series/2) that never merges into native contexts: context runId/templateId/slotId/setupNote filters exclude imported history entirely, exercise/implementation/equipment/role match exactly, instant from/until exclude and count date-only sessions, family membership uses mapped exerciseId only, unknown roles appear by default but explicit roles must be native roles, and the 10000-point budget is shared. To map an exercise after import, re-import it with exerciseId set and onChanged:update.',
          'links':
              'link create requires database/link/expectedRevision/createdAt/confirm:true. A link names id, optional name, distinct shared metrics, optional cadence each-exposure (default) or manual, exactly 2–32 member resolved progression track IDs and a baseline member ID. Members must share the rule kind and coordinated lever shape, the same working-set count, and every shared metric must be controlled at one dimension in every member vector; one track backs at most one link. Membership and baseline are immutable per link identity; later revisions change only name, metrics or cadence, and expectedRevision is compare-and-set. link show takes database/linkId and optional revision; link list returns all revisions; link status evaluates a candidate link against current stored tracks without writing. Consumption is durable: linked sessions resolve shared-metric targets from the link application chain at their start, terminal accept/decline of an each-exposure member appends one shared chain row with compare-and-set against the frozen start state, and manual links advance only via link advance (database/linkId/nextSets/failedSessions/optional cursor/expectedSequence/at/confirm:true). link state takes database/linkId and optional asOf and shows the chain and resolved shared state. link retire requires database/linkId/memberAnchorId/retiredAt/confirm:true and forks one member back to independent local targets; a member retired from one link may later join another. Links never advance programs and terminal receipts never replay.',
          'timing':
              'timer start creates a paused per-set clock; omitted metric selects the published timing metric or the only duration target, and omitted plan resolves the pinned slot timing defaults against its duration suggestion; timer rest times an authored rest occurrence. timer run uses a foreground monotonic clock. Optional stream:true emits NDJSON cue envelopes before the final response. Ctrl-C pauses; unexpected interruption requires explicit timer recover (freeze/adjust). Effort expiry never logs actuals: timer confirm requires expectedSessionVersion and explicit result review. Slots may publish timing defaults with an explicit duration metric, preparation, tempo, near-end and overrun. Explicit clock plans replace defaults. Optional plan.tempo defines repeating effort cues; tempoState exposes logical phase without counting achieved reps. Audio is pending.',
          'execution':
              'execution start/show/list/time/complete/confirm/advance/skip/skip-group/run traverse finite effort/rest occurrences. Timed rests prepare a clock; rest nodes with manual:true have no timer and require execution advance. A rest may declare a range with maxDurationSeconds (repeats: restBetweenMaxSeconds), longer than its durationSeconds minimum: its clock cues rest-ready at the minimum and keeps running to the maximum; pause it (Ctrl-C in run) and execution advance to end the rest whenever ready after the minimum. Every timed rest receipt records restElapsedMilliseconds, the rest the clock measured. execution move takes database/id/expectedVersion/requestId/at and exactly one of occurrenceId (an effort) or groupPath (a structural group such as an exercise repeat, from execution show groups or activity groups): it puts what remains of it next, in its own order, at the cursor while the current effort has no clock, or right after the current rest (e.g. squats while the bench is busy). Nothing is recorded; the rest of the workout keeps its order, execution show lists remaining in walking order, and the version advances so steps prepared before the move conflict. Group skips are refused after a reorder; skip occurrences individually. run advances timed rest boundaries; timed efforts require explicit review, unless the slot timing declares confirmOnTarget:true, in which case reaching the full target duration confirms the set at its suggestions (ending early or manually still needs review). run continuous:true keeps walking (Couch to 5K run/walk intervals): each acknowledged occurrence starts the next until something needs input (a review, an untimed effort, a manual rest, an AMRAP block), Ctrl-C, runForMilliseconds as a total budget, or the end; later steps use request IDs <requestId>-<n>. Actions require execution/session versions and stable requestId; corrections never replay cursor advancement. skip-group requires an explicit groupPath from the current groups list and confirm:true; it preserves existing results. Sets may be logged ahead of the cursor with store complete (e.g. while a station is busy); when the cursor reaches one, acknowledge it with execution advance. complete/confirm/skip/time on an already logged set conflict rather than overwrite it. Scoped windows are not yet supported.',
          'effortRoles':
              'Effort roles are work, warmup, backoff and drop. Prefill and reports keep roles separate; summaries include all except warmups by default and accept an explicit roles list. Graph history sources can explicitly filter by role. Stored progression propose/show/accept/decline accept an optional role, default work; each role has an independent receipt, targets and counter within its run.',
          'activityGroups':
              'activity groups takes definition and optional containing occurrence index. It reports half-open group bounds and authored durations for window scopes, including repeated and nested windows. This is structural inspection only; scoped window execution remains unsupported.',
          'blockProgression':
              'Durable AMRAP block progression (policy bodytmi-block-progression/1): the explicitly confirmed round score of a finished block drives one round slot targets. progression block-propose takes database/sessionId/amrapId/roundSlotId/rule for a finished session whose block checkpoint exists; rule is {performance:{score:confirmedRounds,failureLimit,advancementLimit},increments:{metric:quantity},maximums?,deloadAfter?,deloadDecrements?} and moves only slot-level targets of that round slot. Outcomes: advance (increments), hold (counter reset), failed (one failed exposure), deload (after deloadAfter failures), blocked (maximum or below zero; holds), unknown (block stopped or limited early: neutral) and review (a reviewed effort changed a controlled target). block-show takes the same identity; block-accept/block-decline add expectedVersion and acceptedAt/declinedAt and make an immutable receipt (unknown/review can only be declined; decline holds targets and resolves the counter once). The next repeat-checkpoint start-block for the same run, template, block and round slot starts from the latest decision resolved by the session start and records it in blockTargets. A changed source block makes a pending proposal stale; a newer resolution on the track conflicts. progression block-track takes templateId/amrapId/roundSlotId/optional runId/asOf. store series includeBlocks:true adds a separate blocks section of block results.',
          'phases':
              'Phases are labelled program groups (e.g. accumulation, deload, taper) with optional scoped overrides; no calendar is required. run schedule includeScopes:true lists each day\'s labels. Sessions started inside an overriding phase freeze prescriptionOverrides; history prefill never borrows a result whose metric a phase override prescribed, so a deload does not seed the next ordinary week.',
          'categorical':
              'Slots may declare categories:{<lever>:{values:[2–64 identifiers],default}} (1–16 levers such as grip or hands); values have no implied harder order. Efforts may set settings:{<lever>:value} over the slot defaults. Sessions freeze each set\'s planned settings. session set-settings (session/setId/settings) and store set-settings (database/id/expectedVersion/setId/settings) record which values a completed set actually used; omitted levers count as planned and {} clears the record; skipping drops it. History prefill only borrows results performed with the same settings, summaries show settings/actualSettings, series and records keep performed settings as separate contexts (context filter settings:{lever:value}), and progression holds an exposure with unplanned settings for review (targets and counters unchanged). Ordinal rule levels may also carry settings:{<lever>:value} (every level the same levers; targets optional when settings are present): the current level matches targets and settings, advance/deload proposals report nextLevel, and later store/run starts plan the accepted level\'s settings before history prefill. progression track shows controlledSettings/nextSettings; pure progression ordinal takes currentSettings. Reconciliation receipts adopt targets only, so settings return to the plan after one. A lever may declare tempos:{<value>:{phases:[{id,milliseconds}]}} (exactly one per value; at most one tempo lever per slot, exclusive with timing tempo): each set\'s planned value selects its tempo, so timers and managed execution cue that pattern, session summaries show plannedTempo (and performedTempo when set-settings recorded another value), and ordinal levels or threshold stages that move the lever progress tempo.',
          'presets':
              'Named progression presets: preset publish takes database/preset{id,name?,notes?,ruleType double|threshold|ordinal,rule}/expectedRevision and stores immutable numbered revisions (compare-and-set per id; the rule is validated for its type). preset show takes database/presetId/revision?; preset list returns all revisions. progression propose may take preset:{id,revision} instead of rule/ruleType: the explicit revision supplies the rule, the decision freezes a copy and records preset:{id,revision} as provenance (shown by progression show/accept/decline; archives and backups require that revision to exist with the identical rule). Re-proposing the same rule inline drops the provenance. Later preset revisions never change existing decisions or tracks. A preset prescribes nothing by itself.',
          'bouts':
              'Sequence and repeat nodes may declare bout:true to mark one parent bout (drop set, cluster, rest-pause): at least two effort occurrences, never nested in another bout. Child efforts stay ordinary sets with their own results, roles and progression; store/session summary adds bouts:[{path,sets,status}] and counts.bouts {total,planned,completed,skipped,partial} under policy.boutPolicy bodytmi-bout-count/1, so a report counts the bout once and never as extra sets. Supersets and circuits are plain sequences/repeats with authored rests; drop sets are sequences without rests using role drop. Example examples/structures-practice.json.',
          'setSchemes':
              'A plan node {id,type:variant,slot,lever,branches:{<value>:<activity>}} is an authored structural choice (set scheme such as five triples, six doubles, ten singles) selected by one categorical lever of the slot. Branches cover exactly the lever\'s values, each needs an effort, a variant cannot repeat an enclosing variant\'s lever, AMRAP placements cannot sit inside one, and a branch value is imposed on that slot\'s efforts (an effort cannot contradict it). Sessions freeze variantSelections {variantId:value} and expand only the selected branches; the codec rejects forged selections. Starts choose a progression-controlled lever from the track (ordinal levels with settings), else explicit variants:{<slot>:{<lever>:value}} on session/store/run start, else the lever default; an explicit choice of a progression-controlled lever conflicts. When the structure moves to another branch, a uniform controlled vector broadcasts to the new set count; a non-uniform vector needs reconciliation. activity expand/groups take optional variants:{variantId:value}. Derived workout plans may bind efforts in any branch: graph preview/plan-preview take optional variants:{variantId:value} (default: each lever default), previews record variantSelections and list only the selected branch, store/run starts resolve the session\'s own selection, and bindings into other branches stay inactive (validated at publication). Threshold rules may add stages:{lever,order:[{value,failureLimit,advancementLimit}]} (2–64 distinct lever values, limits in the performance metric\'s dimension, replacing the rule limits for that stage): every working set must plan the same stage value; when failed exposures reach deloadAfter the proposal outcome is stage (next stage, every numeric setting held, failures reset), and at the last stage the configured deload applies (outcome deload) or, without deloadMetrics, outcome stage; both restart at the first stage. Proposals report nextStage; accepted decisions control the lever, so later starts plan that stage; declining a stage holds it and keeps previousFailures+1. Pure progression evaluate takes stage. Staged rules cannot back shared lever links. Failure-driven stages may add cycleRestart:{basis:cycleStart|firstStageExit,increments:{<increment metric>:quantity}}: exhausting the last stage restarts at the first stage at the track\'s cycle reference plus the increments (GZCLP T2: back to 10x3, heavier than last cycle), replacing the deload/restart action (a retest policy still takes precedence). The reference is explicit track state carried through decisions (previousReference), nextState.reference and reconciliations: cycleStart records the values a cycle started at, firstStageExit those at which the first stage was last left; before any reference is known the current values stand in. Pure progression evaluate takes state.reference. stages.advanceOn:success makes waves: advancement moves to the next stage (outcome stage) and the wrap from the last stage to the first applies the rule increments (outcome advance); failures count and deload without moving. Each stage may declare offsets:{<increment metric>:quantity} (nonnegative, the same metrics on every stage) added to the base, so moving between stages shifts values by the offset difference; a shift below zero is blocked. A declined success-mode stage move counts as a success. Example examples/wave-practice.json and wave-propose.json.',
          'unilateralSides':
              'Effort activities may declare side:left|right; absent means not side-specific. Log each side as its own effort occurrence, e.g. a repeat of a sequence of left and right efforts. History prefill only borrows a past result from the same side; summaries show each set side; store/history series and records keep left and right in separate contexts, and the series context filter accepts side. Progression still treats every working set of the slot as one vector. The side does not change load conventions; declare repCounting/sides there for interpretation.',
          'branchedLevels':
              'Ordinal rules may declare successors:{levelId:[levelId,...]}, an acyclic graph of declared harder transitions. With it only declared edges authorize advancement and sibling branches stay incomparable: one successor proposes advance; several propose choice (targets held, candidates listed) and progression accept must name selectedLevel among them; none is blocked. A branched deloadLevel must be a declared ancestor of the current level. Without successors the authored array order applies.',
          'substitution':
              'Temporary substitution (policy bodytmi-substitution/1): store substitute takes database/id/expectedVersion/slotId/scope (occurrence with setId, or remaining)/composition{exercise,implementation,equipment?,setupNote?}/targets?{metric:{source:keep|history|explicit,value?}}; session substitute takes session plus optional history. Unlisted metrics use history (latest finished result for the same template, slot, role, ordinal and replacement); otherwise a target stays unresolved with a reason and completing the set needs an explicit actual. The template never changes; substitutes keep their own series context (substituted:true), never prefill the original slot, are excluded from derived-graph history, and are not proposed for the original progression track. store/session revert-substitution restores planned sets exactly. Substitution and its revert also work mid-workout during guided traversal (e.g. the benches are taken when you reach them): only planned sets ahead of the cursor change, and a set whose effort clock is running or awaiting review must be reviewed or discarded first; rest clocks do not block.',
          'emom':
              'Author an EMOM as a finite repeat of window nodes (e.g. repeat count 12 of a 60 s window containing one effort). checkpoint start takes database/id/sessionId and creates the scoped clock at the first occurrence of an active session (identical retry returns it); then checkpoint reserve, run or action resume/advance/pause with owner samples. Overrun policy bodytmi-window-overrun/1:stop-partial (shown in checkpoint status): boundaries stay on the authored grid; finishing early uses complete-current and the rest of the window is recovery until the boundary and advance-boundary; unfinished work at a boundary blocks advancing until review-expired records an explicit (possibly partial) result or skip-expired confirms a skip, and the next window starts at that same boundary. No clock transition records a result.',
          'amrapBlocks':
              'A plan node {id,type:amrap,amrapId} places a declared block at one point of the finite plan (at most once per block, never inside a repeat or window): it is one traversal occurrence with no sets; execution show reports kind amrap with the block checkpoint status, execution time/complete/skip reject it, and execution advance requires that session block checkpoint to be finished (stop is an explicit skip), recording checkpointId in the receipt. With a traversal, start-block waits until the cursor reaches the placement; group skips may pass it. Unplaced blocks keep running alongside the plan. Scoped window clocks reject plans with placements. A workout definition may declare amraps: 1-16 authored deadline-bounded AMRAP blocks, each {id,durationMilliseconds,maxRounds,maxOccurrences,roundDefinition} like a repeat loop, pinned in the immutable revision; publication checks each is startable. repeat-checkpoint start-block takes database/id/sessionId/amrapId and creates the block ledger from the active session pinned revision (identical retry returns it; one checkpoint per session block). Run, review, correct and finish it with the existing repeat-checkpoint reserve/run/action commands; skipping a block is an explicit confirmed stop action. A session cannot finish until every authored block has a finished checkpoint. The clock never records rounds or reps: only explicit reviews do. repeat-checkpoint series/rounds report amrapId.',
          'windowStatus':
              'activity window-repeat-page previews one paged virtual round using an explicit deadline and safety limits. activity window-repeat-cursor provides caller-owned structural steps and explicit logical clock samples; it does not save or certify results. activity window-repeat-execution adds explicit effort reviews, including while running with an owner clock sample, version-checked result corrections and outcome revisions, explicit boundary batch reviews and round summaries to a caller-owned cursor; it does not persist training sessions. activity window-status takes definition/occurrence/elapsedMilliseconds/windowStarts. It calculates nested authored window deadlines from explicit shared logical milliseconds. activity window-crossing compares two logical samples and identifies the earliest crossed window boundary and its occurrence bounds, including tied deadlines. activity window-transition calculates entered and exited scopes and carries their logical starts to an explicitly selected later occurrence. activity window-clock operates on an explicit caller-owned clock snapshot with start/resume/advance/pause/recover/move actions. Recovery freezes the last sample or accepts explicit adjustmentMilliseconds; samples and adjustments stop at the first deadline. Clock snapshots retain the current occurrence start and boundary paths and unapplied elapsed time; no results are inferred. session window-clock and store window-clock bind caller-owned clock snapshots to a session and require explicit completed or skipped efforts before movement. session window-review and store window-review explicitly complete or skip the current effort and move the caller-owned clock together using session and clock versions; stored review persists the session but not the clock. repeat-checkpoint save/show/list/delete manage inert repeat snapshots; repeat-checkpoint reserve/release explicitly share the profile timing slot; repeat-checkpoint run uses a foreground monotonic clock with optional bounded duration and streamed boundary events, pauses on Ctrl-C, and needs recovery after unexpected interruption; repeat-checkpoint action supports reserved owner-sampled clock epochs, recovery, reviews, corrections, and explicit elapsed samples with checkpoint and execution versions; A repeat checkpoint can name an active session on creation; its session cannot finish until the repeat finishes, and repeat results stay in its own ledger. checkpoint save/show/list/delete manage session-bound snapshots. session rounds and store rounds report explicit completed and partial iterations of a selected finite repeat, without inferring work from time. checkpoint status derives current occurrence, window deadlines, pending boundary reviews and whether recovery is required before a new owner; it does not change state. checkpoint reserve/release explicitly control the profile timing slot; checkpoint action persists owner-supplied clock samples, and checkpoint review atomically saves explicit results and the moved clock. Release and deletion require confirmation; running clocks require recovery after interruption. Window effort reviews may include explicit nonempty observations, including an interrupted termination reason; no interruption is inferred. checkpoint complete-current explicitly records the current effort while leaving the clock on its window, so the remaining time can be used for recovery. checkpoint review-expired-batch records explicitly reviewed efforts and confirmed skips together at a boundary. checkpoint review-expired explicitly completes the current effort and skips remaining planned work atomically at a boundary. checkpoint skip-expired explicitly skips remaining planned work in the expired window and moves its checkpoint atomically, requiring confirm:true. checkpoint advance-boundary moves past expired windows only when all crossed efforts were reviewed. checkpoint advance-rest acknowledges a reached timed rest or confirmed manual rest and prepares the next occurrence paused. checkpoint run uses a foreground monotonic clock until a boundary or optional runForMilliseconds; advanceReviewed:true optionally moves past fully reviewed boundaries and pauses at the next occurrence; stopAtRest:true pauses at the current authored timed-rest target, unless a window boundary comes first; advanceRest:true optionally moves to the next paused occurrence after that target; stream:true emits NDJSON start and boundary events. Ctrl-C pauses; unexpected interruption requires checkpoint action recover. Automatic traversal remains pending.',
          'tempoSample':
              'tempo sample takes tempo/previousElapsedMilliseconds/elapsedMilliseconds and optional includeInitial. It returns the current phase and at most the newest crossed cue from explicit effort-time samples; it does not own a clock, deliver audio or count reps.',
          'unplannedTiming':
              'timer start and execution time/run can time a set without a prescribed duration metric using an explicit plan with unplannedDuration:true and an explicit unused duration metric ID. Specify either effortMilliseconds or openEnded:true; end open-ended effort explicitly. Tempo is optional. Confirming records elapsed duration and requires explicit remaining actuals or acceptSuggested. A slot may instead publish timing with metric and openEnded:true plus optional preparation and tempo; omitted clock plans use the pinned guidance. The workout prescription is unchanged.',
          'roleProgressionPreview':
              'session progression-preview takes session/slotId/rule and optional role, ruleType and state; store progression-preview takes database/id instead of session and optionally useTrack:true to load current run/role lineage instead of state. Active sessions can be previewed but must be finalized before creating durable decisions. Role defaults to work; ruleType defaults to double. Preview is read-only and does not apply targets or create progression decisions.',
          'progressionTrack':
              'progression track takes database/templateId/revision/slotId/asOf and optional runId/role. It reports the latest resolved decision eligible at the cutoff, with controlled targets and current source-change status; omitted runId selects ad hoc sessions. It does not check prescription compatibility or apply progression.',
        }),
      );
      return;
    }
    if (arguments.length == 1 && arguments.single == '--version') {
      stdout.writeln(jsonEncode({'schemaVersion': 1, 'version': '0.1.0'}));
      return;
    }
    if (arguments.length != 2 && arguments.length != 4) {
      throw const BodyTmiException(
        'usage',
        'Expected <group> <action> [--input FILE|-].',
      );
    }
    final command = arguments.take(2).join(' ');
    if ((!commandNames.contains(command) &&
            !storedCommandNames.contains(command) &&
            !foodCommandNames.contains(command) &&
            !sleepCommandNames.contains(command) &&
            !dailyCommandNames.contains(command) &&
            !planningCommandNames.contains(command)) ||
        (arguments.length == 4 && arguments[2] != '--input')) {
      throw const BodyTmiException(
        'usage',
        'Unknown command/option. Use --help.',
      );
    }
    const maxBytes = 8 * 1024 * 1024;
    final inputPath = arguments.length == 4 ? arguments[3] : '-';
    final stream = inputPath == '-' ? stdin : File(inputPath).openRead();
    final bytes = BytesBuilder(copy: false);
    await for (final chunk in stream) {
      if (bytes.length + chunk.length > maxBytes)
        invalid('Request exceeds the 8 MiB resource limit.');
      bytes.add(chunk);
    }
    final request = jsonObject(
      jsonDecode(utf8.decode(bytes.takeBytes())),
      'request',
    );
    final response = planningCommandNames.contains(command)
        ? await executePlanning(command, request)
        : dailyCommandNames.contains(command)
        ? await executeDaily(command, request)
        : sleepCommandNames.contains(command)
        ? await executeSleep(command, request)
        : foodCommandNames.contains(command)
        ? await executeFood(command, request)
        : storedCommandNames.contains(command)
        ? await executeStored(command, request)
        : const Commands().execute(command, request);
    stdout.writeln(jsonEncode(response));
  } on BodyTmiException catch (error) {
    _error(error.code, error.message);
    exitCode = switch (error.code) {
      'not_found' => 3,
      'conflict' || 'in_use' => 5,
      'storage' || 'io' => 4,
      _ => 2,
    };
  } on FormatException catch (error) {
    _error('validation', 'Invalid JSON/text: ${error.message}');
    exitCode = 2;
  } on SqliteException catch (error) {
    _error('storage', error.message);
    exitCode = 4;
  } on FileSystemException catch (error) {
    _error('io', error.message);
    exitCode = 4;
  } catch (error, stack) {
    _error('internal', '$error');
    stderr.writeln(stack);
    exitCode = 70;
  }
}

void _error(String code, String message) => stderr.writeln(
  jsonEncode({
    'schemaVersion': 1,
    'error': {'code': code, 'message': message},
  }),
);
